#!/usr/bin/env python3
"""Generate mechanically matched Dart kernels; --check detects source drift."""
import argparse
from pathlib import Path

FAMILIES = ('scalar', 'packed', 'aligned', 'unaligned')


def generate():
    lines = [
        '// Generated by generate_controlled_kernels.py; do not edit by hand.',
        "part of 'controlled_bench.dart';",
        '',
    ]
    entries = []
    for family in FAMILIES:
        for checks in ('checked', 'guarded', 'unchecked'):
            for unroll in (1, 4):
                name = f'{family}{checks.title()}U{unroll}'
                entries.append((f'{family}-{checks}-u{unroll}', name))
                lines += ["@pragma('vm:never-inline')"]
                if checks == 'unchecked':
                    lines += ["@pragma('vm:unsafe:no-bounds-checks')"]
                lines += [
                    f'void {name}(Float32List samples, Float32List hann,',
                    '    Float32List output, Float32x4List inputVectors,',
                    '    Float32x4List hannVectors, Float32x4List outputVectors,',
                    '    int offset, ByteData sampleBytes) {',
                ]
                if family == 'aligned':
                    lines += ['  final base = offset ~/ 4;']
                if checks == 'guarded':
                    if family == 'aligned':
                        condition = ('offset < 0 || offset % 4 != 0 || '
                                     'base > inputVectors.length - width ~/ 4 || '
                                     'hannVectors.length < width ~/ 4 || '
                                     'outputVectors.length < width ~/ 4')
                    elif family in ('packed', 'unaligned'):
                        condition = ('offset < 0 || offset > samples.length - width || '
                                     'hannVectors.length < width ~/ 4 || '
                                     'outputVectors.length < width ~/ 4')
                    else:
                        condition = ('offset < 0 || offset > samples.length - width || '
                                     'hann.length < width || output.length < width')
                    lines += [f'  if ({condition}) {{',
                              "    throw RangeError('Invalid window range');", '  }']
                limit = 'width' if family == 'scalar' else 'width ~/ 4'
                lines += [f'  for (var j = 0; j < {limit}; j += {unroll}) {{']
                for lane in range(unroll):
                    j = 'j' if lane == 0 else f'(j + {lane})'
                    if family == 'scalar':
                        lines += [f'    output[{j}] = samples[offset + {j}] * hann[{j}];']
                    elif family == 'aligned':
                        lines += [f'    outputVectors[{j}] = inputVectors[base + {j}] * hannVectors[{j}];']
                    elif family == 'unaligned':
                        helper = 'loadUnalignedUnchecked' if checks == 'unchecked' else 'loadUnalignedChecked'
                        lines += [f'    final v{lane} = {helper}(sampleBytes, (offset + {j} * 4) * 4);',
                                  f'    outputVectors[{j}] = v{lane} * hannVectors[{j}];']
                    else:
                        lines += [f'    final i{lane} = offset + {j} * 4;',
                                  f'    final v{lane} = Float32x4(samples[i{lane}], samples[i{lane} + 1],',
                                  f'        samples[i{lane} + 2], samples[i{lane} + 3]);',
                                  f'    outputVectors[{j}] = v{lane} * hannVectors[{j}];']
                lines += ['  }', '}', '']
    lines += ['const controlledKernels = <String, WindowKernel>{']
    lines += [f"  '{mode}': {name}," for mode, name in entries]
    lines += ['};', '']
    return '\n'.join(lines)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = Path(__file__).with_name('controlled_kernels.g.dart')
    source = generate()
    if args.check:
        if not target.exists() or target.read_text(encoding='utf-8') != source:
            raise SystemExit('Generated kernels are stale; run generate_controlled_kernels.py')
        print('Generated kernels match the generator.')
    else:
        target.write_text(source, encoding='utf-8')
